<?php $typeLabel=static fn(string$type):string=>['PERCENT_ORDER'=>'% off order','FIXED_ORDER'=>'Amount off order','PERCENT_PRODUCT'=>'% off product','PERCENT_CATEGORY'=>'% off category','FREE_DELIVERY'=>'Free delivery'][$type]??$type; ?>
<section class="page-head"><div><p class="eyebrow">Promotions</p><h1>Discount codes</h1><p class="muted">Codes customers can enter at checkout. The server always recomputes and validates the discount — nothing here is trusted from the browser.</p></div><a class="button primary" href="/merchant/discounts/create">Add discount code</a></section>
<?php if(!$codes):?><section class="empty-state panel"><div class="empty-icon">%</div><h2>No discount codes yet</h2><p>Create a code like <code>SAVE10</code> for a percentage off, a fixed amount, a specific product or category, or free delivery.</p><a class="button primary" href="/merchant/discounts/create">Create first code</a></section><?php else:?><section class="panel flush table-wrap"><table><thead><tr><th>Code</th><th>Type</th><th>Value</th><th>Scope</th><th>Window</th><th>Used</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($codes as$code):?><tr><td><strong><?= e($code['code']) ?></strong></td><td><?= e($typeLabel($code['type'])) ?></td><td><?php if($code['type']==='PERCENT_ORDER'||$code['type']==='PERCENT_PRODUCT'||$code['type']==='PERCENT_CATEGORY'):?><?= e($code['value']) ?>%<?php elseif($code['type']==='FIXED_ORDER'):?><?= e($code['value']) ?><?php else:?>—<?php endif ?></td><td><?= e($code['product_name']??$code['category_name']??'Whole order') ?></td><td><?php if($code['starts_at']||$code['ends_at']):?><?= $code['starts_at']?e(gmdate('M j',strtotime($code['starts_at']))):'Now' ?> – <?= $code['ends_at']?e(gmdate('M j, Y',strtotime($code['ends_at']))):'No end' ?><?php else:?>Always on<?php endif ?></td><td><?= e($code['times_used']) ?><?= $code['usage_limit']?' / '.e($code['usage_limit']):'' ?></td><td><span class="badge <?= $code['status']==='ACTIVE'?'active':'inactive' ?>"><?= e($code['status']) ?></span></td><td class="row-actions"><a class="button compact secondary" href="/merchant/discounts/<?= e($code['id']) ?>/edit">Edit</a><form method="post" action="/merchant/discounts/<?= e($code['id']) ?>/toggle"><?= csrf_field() ?><button class="button compact ghost"><?= $code['status']==='ACTIVE'?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach ?></tbody></table></section><?php endif ?>
